"""Repair queue (schema.sql section 8)."""
import uuid
from datetime import datetime
from decimal import Decimal
from typing import Any

from sqlalchemy import DateTime, ForeignKey, Integer, Numeric, String, Text, func, text
from sqlalchemy.dialects.postgresql import JSONB, UUID
from sqlalchemy.orm import Mapped, mapped_column

from app.models.base import Base, PriorityEnum, QueueStatusEnum


class RepairQueueItem(Base):
    __tablename__ = "repair_queue"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    # RQ-000001 ... generated by the DATABASE default - never set it from Python.
    queue_id: Mapped[str] = mapped_column(
        String(20), unique=True,
        server_default=text("('RQ-' || lpad(nextval('repair_queue_seq')::text, 6, '0'))"),
    )
    trade_pk: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), ForeignKey("trades.id", ondelete="CASCADE"), unique=True)
    priority: Mapped[str] = mapped_column(PriorityEnum, index=True)
    status: Mapped[str] = mapped_column(QueueStatusEnum, server_default="OPEN", index=True)
    risk_score_at_entry: Mapped[Decimal] = mapped_column(Numeric(5, 4))
    suggested_fixes: Mapped[list[dict[str, Any]] | None] = mapped_column(JSONB)
    assigned_to: Mapped[int | None] = mapped_column(Integer, ForeignKey("users.id"), index=True)
    assigned_by: Mapped[int | None] = mapped_column(Integer, ForeignKey("users.id"))
    assigned_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    applied_fix: Mapped[str | None] = mapped_column(Text)
    applied_by: Mapped[int | None] = mapped_column(Integer, ForeignKey("users.id"))
    applied_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    resolution_note: Mapped[str | None] = mapped_column(Text)
    resolved_by: Mapped[int | None] = mapped_column(Integer, ForeignKey("users.id"))
    resolved_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
